// The "File generated by Focal Registry" pill for the two MindMerge toolbars that can have one of
// the Scan Notes mirror files open. It draws nothing at all for any other note, so an ordinary
// note's toolbar is exactly what it was. Nothing is written into the note: the path alone decides.
import { isGeneratedSource } from "../../shared/generatedSource";

// The sweep 2 wording, word for word. True where the open note is a copy kept in the database
// (the Brain tab): an edit made there is kept, and only the file on disk is replaced.
const HOVER_FOR_A_COPY =
  "Focal Registry rewrites this file on every sync. Edit the note here; changes typed into the file elsewhere are replaced.";
// The Documents tab saves straight into the file, so "edit the note here" would send the typing
// into the very file the next sync replaces. Same first sentence, and a second one that is true there.
const HOVER_FOR_THE_FILE =
  "Focal Registry rewrites this file on every sync. Changes typed into the file are replaced, including here; edit the notes in Scan Notes.";

interface Props {
  /** The file the open note came from, or the open file itself. Null for a note written in the app. */
  sourcePath: string | null;
  /** Set where the editor saves into the file itself rather than into a database copy of it. */
  editsFile?: boolean;
}

export default function GeneratedPill({ sourcePath, editsFile = false }: Props) {
  if (!isGeneratedSource(sourcePath)) return null;
  // Two spans because the outer one is the room the toolbar can spare and the inner one is the
  // pill, which shortens to fit that room instead of pushing its neighbours.
  return (
    <span className="mm-genslot">
      <span className="mm-genpill" title={editsFile ? HOVER_FOR_THE_FILE : HOVER_FOR_A_COPY}>
        File generated by Focal Registry
      </span>
    </span>
  );
}
